/* Cabeçalho: sem estilos exclusivos; utiliza a folha do componente principal. */
.app-notification-button{position:relative;width:40px;height:40px;display:grid;place-items:center;padding:0;border:0;border-radius:10px;background:transparent;color:#fff;cursor:pointer}.app-notification-button:hover{background:rgba(255,255,255,.09)}.app-notification-button svg{width:22px;height:22px}.app-notification-badge{position:absolute;right:2px;top:2px;min-width:17px;height:17px;display:grid;place-items:center;padding:0 4px;border:2px solid var(--primary);border-radius:999px;background:#d92d20;color:#fff;font-size:9px;font-weight:900;line-height:1}

/* Barra de título: sem estilos exclusivos; utiliza a folha do componente principal. */

/* solicitacoes.cliente.avaliar_experiencia · formulário de avaliação */
.evaluation-page{
  width:min(100%,720px);
  margin:0 auto;
  padding:22px 18px 48px;
}
.evaluation-intro{margin:0 2px 18px}
.evaluation-eyebrow{
  display:block;
  margin-bottom:7px;
  color:var(--gold);
  font-size:11px;
  font-weight:900;
  letter-spacing:.08em;
}
.evaluation-intro h1{
  margin:0;
  color:var(--primary);
  font-size:clamp(24px,6vw,32px);
  line-height:1.12;
}
.evaluation-intro p{
  margin:9px 0 0;
  color:var(--muted);
  font-size:13px;
  line-height:1.55;
}
.evaluation-form{display:grid;gap:12px}
.evaluation-card{
  border:1px solid var(--line);
  border-radius:16px;
  padding:17px;
  background:var(--surface);
}
.evaluation-professional{
  display:flex;
  gap:12px;
  align-items:center;
  margin-bottom:12px;
}
.evaluation-professional strong,
.evaluation-professional span{display:block}
.evaluation-professional strong{color:var(--primary);font-size:14px}
.evaluation-professional span{margin-top:3px;color:var(--muted);font-size:11px}
.evaluation-avatar{
  display:grid;
  width:46px;
  height:46px;
  flex:0 0 46px;
  place-items:center;
  border-radius:50%;
  background:#e8eef5;
  color:var(--primary);
  font-size:13px;
  font-weight:900;
}
.evaluation-question h2{
  margin:0;
  color:var(--primary);
  font-size:15px;
}
.evaluation-question p{
  margin:5px 0 12px;
  color:var(--muted);
  font-size:12px;
  line-height:1.5;
}
.star-field{margin:0;padding:0;border:0}
.star-field>small{
  display:block;
  margin-top:5px;
  color:var(--muted);
  font-size:10px;
}
.star-rating{
  display:inline-flex;
  flex-direction:row-reverse;
  justify-content:flex-end;
  gap:4px;
}
.star-rating input{
  position:absolute;
  width:1px;
  height:1px;
  opacity:0;
  pointer-events:none;
}
.star-rating label{
  display:inline-block;
  color:#c8d0da;
  font-size:34px;
  line-height:1;
  cursor:pointer;
  transition:transform .12s ease,color .12s ease;
}
.star-rating label:hover{transform:scale(1.06)}
.star-rating label:hover,
.star-rating label:hover~label,
.star-rating input:checked~label{color:var(--gold)}
.star-rating input:focus-visible+label{
  outline:2px solid var(--primary-soft);
  outline-offset:3px;
  border-radius:5px;
}
.evaluation-comment>span{
  display:block;
  margin-bottom:8px;
  color:var(--primary);
  font-size:13px;
  font-weight:800;
}
.evaluation-comment>span small{
  color:var(--muted);
  font-size:10px;
  font-weight:700;
}
.evaluation-comment textarea{
  width:100%;
  min-height:120px;
  resize:vertical;
  border:1px solid var(--line);
  border-radius:12px;
  padding:12px 13px;
  background:#fff;
  color:var(--text);
  font:inherit;
  font-size:13px;
  line-height:1.5;
  outline:0;
}
.evaluation-comment textarea:focus{
  border-color:var(--primary-soft);
  box-shadow:0 0 0 3px rgba(23,60,107,.10);
}
.evaluation-comment>small{
  display:block;
  margin-top:7px;
  color:var(--muted);
  font-size:10px;
  line-height:1.45;
}
.evaluation-note{
  display:grid;
  gap:4px;
  border-radius:13px;
  padding:13px 14px;
  background:#f3f6fa;
}
.evaluation-note strong{
  color:var(--primary);
  font-size:11px;
}
.evaluation-note p{
  margin:0;
  color:var(--muted);
  font-size:10px;
  line-height:1.5;
}
.evaluation-actions{margin-top:4px}
.evaluation-submit{
  width:100%;
  min-height:54px;
  border:0;
  border-radius:13px;
  padding:14px 18px;
  background:var(--primary);
  color:#fff;
  font-size:14px;
  font-weight:800;
  cursor:pointer;
}
.sr-only{
  position:absolute!important;
  width:1px!important;
  height:1px!important;
  padding:0!important;
  margin:-1px!important;
  overflow:hidden!important;
  clip:rect(0,0,0,0)!important;
  white-space:nowrap!important;
  border:0!important;
}
@media(min-width:700px){
  .evaluation-page{padding-top:30px}
  .evaluation-card{padding:20px}
}

.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

.prototype-drawer.open { display: block; }

.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7, 16, 30, .60);
}

.drawer-panel {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(80vw, 360px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #3b4a7d;
  color: #fff;
  box-shadow: 12px 0 30px rgba(0, 0, 0, .32);
}

.drawer-top {
  flex: 0 0 auto;
  min-height: 106px;
  padding: 30px 22px 20px;
  display: flex;
  align-items: center;
}

.drawer-identity {
  min-width: 0;
  display: flex;
  gap: 14px;
  align-items: center;
}

.drawer-avatar {
  flex: 0 0 56px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, .20);
  border-radius: 50%;
  background: #dbeafe;
  color: #1e3a8a;
  font-size: 20px;
  font-weight: 800;
}

.drawer-profile { min-width: 0; }
.drawer-profile strong,
.drawer-profile small { display: block; }
.drawer-profile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 600;
}
.drawer-profile small {
  margin-top: 2px;
  color: #bfdbfe;
  font-size: 11px;
  font-weight: 400;
  text-transform: lowercase;
}

.drawer-online {
  flex: 0 0 auto;
  width: calc(100% - 44px);
  margin: 0 22px 10px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, .08);
  color: #fff;
  text-align: left;
  cursor: pointer;
}
.drawer-online-copy strong,
.drawer-online-copy small { display: block; }
.drawer-online-copy strong { font-size: 13px; }
.drawer-online-copy small { margin-top: 2px; color: #bfdbfe; font-size: 10px; }
.online-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 4px rgba(74, 222, 128, .14);
}
.drawer-online.is-offline .online-dot { background: #98a2b3; box-shadow: none; }
.online-switch { position: relative; width: 38px; height: 22px; border-radius: 999px; background: #22c55e; }
.online-switch b { position: absolute; top: 3px; right: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; }
.drawer-online.is-offline .online-switch { background: #64748b; }
.drawer-online.is-offline .online-switch b { right: 19px; }

.drawer-nav {
  flex: 1 1 auto;
  min-height: 0;
  display: block;
  margin: 0;
  padding: 0 0 8px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, .35) transparent;
}
.drawer-nav::-webkit-scrollbar { width: 5px; }
.drawer-nav::-webkit-scrollbar-thumb { border-radius: 999px; background: rgba(255, 255, 255, .35); }

.drawer-nav button {
  width: 100%;
  min-height: 51px;
  padding: 14px 22px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 15px;
  align-items: center;
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}
.drawer-nav button:hover { background: rgba(255, 255, 255, .08); }
.drawer-icon { flex: 0 0 20px; width: 20px; height: 20px; color: #aebee5; }

.drawer-footer {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 16px 22px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  background: rgba(0, 0, 0, .10);
}
.drawer-footer-top { display: flex; justify-content: space-between; gap: 12px; align-items: center; }
.drawer-logout {
  min-height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 14px;
  cursor: pointer;
}
.drawer-logout svg { width: 18px; height: 18px; color: #aebee5; }
.drawer-footer small { color: #aebee5; font-size: 10px; }
.drawer-emergency {
  min-height: 41px;
  border: 1px solid rgba(255, 255, 255, .54);
  border-radius: 999px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.drawer-emergency:hover { background: rgba(255, 255, 255, .08); }

@media (max-width: 420px) {
  .drawer-panel { width: 80vw; }
  .drawer-top { padding-top: 24px; }
}
